-- 033_preparedness.sql
--
-- Disaster Risk: preparedness (preparedness.php, vulnerable_residents.php,
-- disaster_risk.php task actions, src/pages/Preparedness.jsx):
--
-- address_streets.flood_level / flood_share / flood_checked_at
--        Each street's Project NOAH 100-year flood level (0 none, 1 low,
--        2 medium, 3 high; NULL = no street shape to check). Filled by
--        034_street_flood_levels.sql, generated by scripts/streets_flood/.
-- emergency_hotlines
--        Numbers shown with tap-to-call on Disaster Risk, Home and
--        /preparedness. Seeded only with numbers that are national and
--        stable (911, Red Cross 143): staff add the barangay's and the city's.
-- preparedness_guides
--        Before / during / after steps per hazard, one step per line.
--        Published prose: keeps the capitalisation staff type (like the
--        About page), not ALL CAPS. Filipino version optional.
-- alert_task_templates / alert_task_progress
--        The officials' checklist per alert level. An advisory shows the
--        tasks of its level and every level below it; ticks are kept per
--        advisory with who and when, and the task's wording at that time.
--
-- Additive only, safe to re-run:
--     mysql -u root barangay_bims < backend/migrations/033_preparedness.sql

ALTER TABLE `address_streets`
  ADD COLUMN IF NOT EXISTS `flood_level` TINYINT NULL DEFAULT NULL AFTER `source`,
  ADD COLUMN IF NOT EXISTS `flood_share` DECIMAL(4,2) NULL DEFAULT NULL AFTER `flood_level`,
  ADD COLUMN IF NOT EXISTS `flood_checked_at` DATE NULL DEFAULT NULL AFTER `flood_share`;

CREATE TABLE IF NOT EXISTS `emergency_hotlines` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(120) NOT NULL,
  `number` VARCHAR(40) NOT NULL,
  `category` VARCHAR(20) NOT NULL DEFAULT 'other',
  `note` VARCHAR(200) NULL DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `sort_order` INT NOT NULL DEFAULT 0,
  `updated_by` INT NULL DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_hotline_number` (`number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT IGNORE INTO `emergency_hotlines` (`name`, `number`, `category`, `note`, `sort_order`) VALUES
('National Emergency Hotline', '911', 'emergency', 'Police, fire and medical emergencies, nationwide, free', 1),
('Philippine Red Cross', '143', 'medical', 'Ambulance, rescue and blood services', 2);

CREATE TABLE IF NOT EXISTS `preparedness_guides` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `hazard` VARCHAR(20) NOT NULL,
  `phase` VARCHAR(10) NOT NULL,
  `body` TEXT NOT NULL,
  `body_fil` TEXT NULL DEFAULT NULL,
  `updated_by` INT NULL DEFAULT NULL,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_guide` (`hazard`, `phase`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT IGNORE INTO `preparedness_guides` (`hazard`, `phase`, `body`) VALUES
('typhoon', 'before', 'Follow PAGASA bulletins and the barangay advisories on PB2Link.\nKnow your nearest evacuation center and how to walk there (Disaster Risk page).\nPrepare your go-bag and keep it near the door.\nTie down or bring inside anything the wind can throw: roofing, signs, plants, laundry poles.\nTrim tree branches that hang over your roof or power lines.\nCharge phones and power banks; keep a flashlight, a battery radio and spare batteries.\nStore drinking water and food for at least three days.'),
('typhoon', 'during', 'Stay indoors and away from windows and glass doors.\nKeep listening to advisories by radio, SMS or PB2Link.\nLeave as soon as the barangay tells you to evacuate. If your street floods, leave earlier.\nSwitch off the main power if water starts to come into the house.\nIf the wind suddenly stops, the eye may be passing: stay inside, the wind will come back from the other side.'),
('typhoon', 'after', 'Go home only when the barangay says it is safe.\nStay away from fallen power lines and report them to the barangay or the electric company.\nCheck your house for damage before going in.\nBoil drinking water or use treated water until the supply is declared safe.\nEmpty containers and clear stagnant water to stop mosquitoes (dengue).'),
('flood', 'before', 'Check your street''s flood level on this page and plan when your family will leave.\nMove appliances, documents and valuables to a higher place.\nKeep documents and medicines in waterproof bags.\nClear the drainage and canals near your house; report blocked drains to the barangay.\nAgree on a meeting place in case your family gets separated.'),
('flood', 'during', 'Evacuate early, before the water gets deep. Bring your go-bag.\nSwitch off electricity at the main switch and close the gas tank before leaving.\nNever walk or drive through moving floodwater: water at knee height can knock you down, and a car can be swept away.\nStay away from canals, rivers and open drains.\nIf you are trapped, go to the highest floor or the roof and call for help.'),
('flood', 'after', 'Return only when the barangay says it is safe.\nDo not touch electrical equipment while it or you are wet; have it checked before using it.\nIf you waded in floodwater, especially with wounds, see a doctor or the health center: leptospirosis can be prevented with early medicine.\nThrow away food and drinks that touched floodwater.\nClean and disinfect the house; wear boots and gloves.'),
('earthquake', 'before', 'Fix heavy furniture, cabinets and shelves to the wall.\nKnow the safe spots in each room (under a sturdy table) and the way out.\nKeep a flashlight and shoes near your bed.\nJoin the barangay earthquake drill. Cavite is near the West Valley Fault.'),
('earthquake', 'during', 'DROP, COVER and HOLD ON under a sturdy table until the shaking stops.\nStay away from windows, glass and things that can fall.\nIf you are outside, move to an open area away from buildings, posts, walls and trees.\nDo not run out of the building while it is shaking, and do not use elevators.'),
('earthquake', 'after', 'Expect aftershocks: drop, cover and hold on again when they come.\nCheck yourself and others for injuries.\nIf you smell gas, do not light anything or switch anything on; open windows and leave.\nLeave buildings with large cracks and do not go back in.\nFollow PHIVOLCS updates and do not spread rumours.'),
('fire', 'before', 'Have old or damaged wiring checked; do not overload outlets with extension cords.\nNever leave cooking, candles or mosquito coils unattended.\nKeep matches and lighters away from children.\nKeep a fire extinguisher, or a pail of water or sand, within reach.\nKnow two ways out of your house.'),
('fire', 'during', 'Shout to warn everyone and get out at once.\nCall 911 or the fire station once you are outside.\nStay low under the smoke; cover your nose and mouth with a wet cloth.\nFeel a door before opening it: if it is hot, use another way out.\nIf your clothes catch fire: STOP, DROP and ROLL.\nNever go back inside for belongings.'),
('fire', 'after', 'Do not go back in until the firefighters say it is safe.\nHave the wiring checked before switching the power back on.\nGo to the barangay hall for help with temporary shelter and documents.');

CREATE TABLE IF NOT EXISTS `alert_task_templates` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `alert_level` ENUM('Advisory','Watch','Warning','Severe') NOT NULL,
  `task` VARCHAR(255) NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `updated_by` INT NULL DEFAULT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_task` (`alert_level`, `task`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT IGNORE INTO `alert_task_templates` (`alert_level`, `task`, `sort_order`) VALUES
('Advisory', 'Monitor PAGASA bulletins and the live hazard feeds', 1),
('Advisory', 'Check that the BDRRM team can be reached (mobiles and radios)', 2),
('Advisory', 'Inspect drains and canals on high flood-risk streets', 3),
('Watch', 'Prepare the evacuation centers: open, clean, water, lights, supplies', 1),
('Watch', 'Pre-position rescue equipment and the barangay vehicle', 2),
('Watch', 'Review the vulnerable residents list for high-risk streets', 3),
('Watch', 'Coordinate with the City DRRM Office', 4),
('Warning', 'Start pre-emptive evacuation of high-risk streets, seniors and PWDs first', 1),
('Warning', 'Open the evacuation centers and keep occupancy updated on PB2Link', 2),
('Warning', 'Deploy the rescue team on standby', 3),
('Severe', 'Carry out forced evacuation of high-risk streets', 1),
('Severe', 'Send status reports to the City DRRM Office every hour', 2),
('Severe', 'Suspend non-essential barangay services', 3);

CREATE TABLE IF NOT EXISTS `alert_task_progress` (
  `alert_id` INT NOT NULL,
  `task_id` INT NOT NULL,
  `task_text` VARCHAR(255) NOT NULL,
  `done_by` INT NULL DEFAULT NULL,
  `done_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`alert_id`, `task_id`),
  KEY `idx_task_progress_task` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
